import imageAssets from './workshop-seedance25-assets.json';
import assistantExample from './workshop-seedance25-assistant-example.json';
import type { Curriculum } from './workshop-content';
import type { LessonStep, WorkshopTechnique } from '../content/workshop/types';
import { seedanceCoursePrompts, type PromptPair } from './workshop-seedance-masterclass-prompts';
import { seedance25Prompts as p } from './workshop-seedance25-prompts';

/** Extends the seven stable progress keys with assessed practice, not a new completion schema. */
export function expandSeedance25(course: Curriculum, locale: 'vi' | 'en'): Curriculum {
  const t = (vi: string, en: string) => locale === 'vi' ? vi : en;
  const pick = (pair: PromptPair) => pair[locale === 'vi' ? 0 : 1];
  const s = (title: PromptPair, instruction: PromptPair, save: string, prompt?: PromptPair, kind: LessonStep['promptKind'] = 'planning', worksheet?: PromptPair, tool = 'ChatGPT / Claude'): LessonStep => ({
    title: pick(title), instruction: pick(instruction), save, tool,
    ...(prompt ? { prompt: prompt[1], promptVi: prompt[0], promptLanguage: 'en', promptFormat: 'text', promptKind: kind, promptEvidence: t('Bài luyện tập do GenYZ biên soạn, chưa chạy thử với Seedance. Nguồn gốc của từng ảnh minh họa được ghi riêng, và các ảnh này không cho thấy việc tạo video đã thành công.', 'GenYZ practice exercise, not yet test-run with Seedance. Where each image came from is recorded separately, and the images do not show that video generation worked.') } as const : {}),
    ...(worksheet ? { resultText: pick(worksheet) } : {}),
  });
  const image = (name: string, label: PromptPair, width = 1536, height = 1024) => ({ label: pick(label), src: `/api/workshop/examples/sd25-${name}.png`, kind: 'image' as const, width, height });
  const optional = (id: string, title: PromptPair, goal: PromptPair, input: PromptPair, steps: LessonStep[], check: PromptPair, fix: PromptPair): WorkshopTechnique => ({ id, title: `${t('Tùy chọn', 'Optional')} · ${pick(title)}`, goal: pick(goal), input: pick(input), steps, check: pick(check), fix: pick(fix) });
  const [story, references, planning, frames, motion, review, delivery] = course.lessons;

  course.courseTitle = t('Seedance 2.5 · Từ clip đầu tiên đến bộ phim của bạn', 'Seedance 2.5 · From Your First Clip to Your Own Film');
  course.workbookName = 'GenYZ-Seedance-2.5';
  course.durationLabel = t("7 bài · 8-12 giờ cơ bản + 6-10 giờ nâng cao · chưa gồm thời gian chờ tạo và dự án cuối khóa", "7 modules · 8-12 hours for the core lessons + 6-10 hours of advanced practice · allow extra time for generation and your final project");
  course.preparation.intro = t('Bắt đầu với câu chuyện “Ai đang gọi mình?” và làm quen với các công cụ. Tiếp theo, tạo nhân vật ở bài 2, bối cảnh và khung đầu ở bài 3, viết prompt ở bài 4, rồi tạo clip đầu tiên ở bài 5. Khi đã làm theo hướng dẫn, đổi một điều kiện để thử cách khác, rồi thực hiện dự án mới của riêng mình. Bạn không cần biết lập trình. Thời lượng gợi ý giúp bạn sắp xếp việc học, không bảo đảm thành thạo sau một buổi.', 'Start with the story “Who Is Calling Me?” and get to know the tools. Create the character in Module 2, the location and starting frame in Module 3, write the prompt in Module 4, then generate your first clip in Module 5. After the guided version, change one condition and make a project of your own. You do not need to know how to code. The schedule helps you plan; it does not promise mastery in one sitting.');
  course.preparation.steps.unshift({ heading: t('Hai cách học', 'Two ways to learn'), text: t('Đường video dùng Seedance 2.5 qua một nhà cung cấp và cần ngân sách; lưu clip thật cùng nhật ký mỗi lần tạo. Đường chuẩn bị dành cho lúc chưa có credit: làm ảnh, prompt, storyboard và animatic (chuỗi ảnh tĩnh dựng theo nhịp thời gian). Mục chưa chạy ghi “chưa thử video”. Animatic vẫn giúp bạn luyện kể chuyện, nhưng không chứng minh kỹ năng tạo video. Dấu hoàn thành chỉ ghi tiến độ, không phải chứng chỉ.', 'The video path uses Seedance 2.5 through a provider and needs a budget. Save the real clips and a log for every take. The preparation path is for when you have no credits: make images, prompts, a storyboard and an animatic (still images arranged into a rough edit). Mark anything you have not run “video not yet tested.” An animatic still teaches story rhythm, but it does not show that you can generate video. Completion marks help you track your progress; they do not certify your skills.') });
  course.preparation.note = t('Ảnh thực hành được tạo bằng GPT Image trong Codex. Video minh họa Seedance 2.5, các cặp ví dụ lỗi và sửa lỗi, cùng bài thử với người mới học thật vẫn đang chờ thực hiện. Tính năng nhà phát triển công bố có thể không xuất hiện trong mọi giao diện. Trước mỗi lần tạo, kiểm tra model, chế độ, đầu vào và giá.', 'The practice images were generated with GPT Image in Codex. Seedance 2.5 video demonstrations, video failure-and-repair pairs and a real beginner pilot remain pending. A capability advertised by the developer may not appear in every interface. Before each generation, check the model, mode, inputs and price.');
  const seedanceTool = course.tools.find(tool => tool.name === 'Seedance');
  if (seedanceTool) { seedanceTool.name = 'Seedance 2.5'; seedanceTool.href = 'https://seed.bytedance.com/en/seedance2_5'; }
  course.tools.push({ name: 'Higgsfield', href: 'https://higgsfield.ai/', purpose: t('Một cách để dùng Seedance 2.5. Kiểm tra các chế độ tài khoản của bạn dùng được; bài thực hành không bắt buộc dùng nhà cung cấp này.', 'One way to reach Seedance 2.5. Check which modes your account can use; this provider is not required.') }, { name: 'Topview', href: 'https://www.topview.ai/', purpose: t('Một cách truy cập khác. Kiểm tra model và báo giá trước khi tạo.', 'Another way to get access. Check the model and quote before you generate.') });
  course.glossary.push(
    ['Blocking', t('Vị trí đứng và đường đi của nhân vật trong cảnh.', 'Where a character stands and the path they move along in the scene.')],
    ['Screen direction', t('Hướng chuyển động sang trái hay sang phải trên màn hình; nếu máy quay chuyển sang phía bên kia, hướng này có thể bị đảo.', 'Whether movement goes left or right on screen; if the camera moves to the other side, the direction can flip.')],
    ['Omni reference', t('Dùng nhiều loại tham chiếu để dẫn dắt nhân vật, bối cảnh, chuyển động hoặc âm thanh; mỗi tham chiếu làm được việc gì còn tùy chế độ.', 'Using several kinds of reference to guide the character, setting, movement or sound; what each reference can do depends on the mode.')],
    ['Parallax', t('Khi máy quay di chuyển, vật ở gần và vật ở xa dịch chuyển khác nhau trong khung hình.', 'When the camera moves, near objects and distant objects shift by different amounts in the frame.')],
    ['Draft / finalize', t('Quy trình tạo bản nháp rồi hoàn thiện đúng job đó, khi nhà cung cấp hỗ trợ; khác với tạo mới hoặc upscale.', 'A workflow where you make a draft and then finalize that same job, when the provider supports it; it is different from a new generation or an upscale.')],
    ['Animatic', t('Chuỗi ảnh tĩnh được dựng theo thời gian để kiểm tra nhịp của câu chuyện.', 'Still images timed in sequence so you can check the rhythm of the story.')],
  );

  const firstFrameGuide: LessonStep = {
    title: t('Nhận biết ô ảnh đầu để dùng ở bài 5', 'Find the starting-frame slot for Module 5'),
    instruction: t('Ở bước này, bạn chỉ cần xem giao diện. Chưa cần có ảnh, tải ảnh lên hay bấm tạo video.', 'For now, just look at the interface. You do not need an image, an upload or a video generation yet.'),
    instructionPoints: locale === 'vi' ? [
      'Model là tên công cụ tạo video: tìm Seedance 2.5 trong danh sách model của nhà cung cấp.',
      'Chế độ (mode) là cách đưa nội dung vào công cụ. Trong bài này, bạn dùng ảnh để tạo video (image-to-video): một ảnh đứng yên sẽ trở thành đoạn phim có chuyển động.',
      'Khung hình đầu (first frame / start image) là ảnh xuất hiện ở lúc video bắt đầu. Tìm ô tải ảnh có vai trò này; tên nút có thể khác tùy trang.',
      'Ảnh tham chiếu (reference image) chỉ giúp AI biết nhân vật hoặc bối cảnh trông thế nào; nó không mặc nhiên là khung hình đầu.',
      'Nếu không thấy ô phù hợp, đừng tải ảnh vào một ô tham chiếu bất kỳ. Kiểm tra chế độ bạn đang dùng; nếu tài khoản chưa hỗ trợ, giữ lại ảnh và prompt để làm tiếp khi có quyền truy cập. Các chế độ khác được giải thích ở bài 6.',
    ] : [
      'Model means the video generator: look for Seedance 2.5 in your provider’s model list.',
      'Mode means how you supply the input. This module uses image-to-video: a still image becomes a moving clip.',
      'The first frame / start image is the picture shown at the beginning of the video. Look for an upload slot with that role; the button label may differ between providers.',
      'A reference image guides the character or setting; it does not automatically become the first frame.',
      'If the slot is unavailable, do not use an arbitrary reference slot. Check the selected mode; if your account does not support it, keep your image and prompt until access is available. Other modes are explained in Module 6.',
    ],
    resultTitle: t('Ví dụ: nhận biết ô ảnh đầu', 'Example: recognizing the starting-frame slot'),
    resultText: t(
      'VÍ DỤ VỀ ẢNH VÀ CHUYỂN ĐỘNG\nBạn có một ảnh Lan đứng trước chiếc ghế. Bạn muốn video bắt đầu đúng từ hình ảnh đó, rồi Lan bước hai bước.\n\n- Ảnh Lan đứng trước ghế → đưa vào ô ảnh đầu.\n- Câu “Lan bước hai bước rồi dừng” → là yêu cầu về chuyển động, đã viết thành prompt ở bài 4.\n- Kết quả mong đợi → video bắt đầu với Lan ở vị trí trong ảnh, sau đó cô mới bước đi. Đây là ví dụ dự kiến, chưa phải video đã tạo.\n\nBÂY GIỜ BẠN CẦN LÀM GÌ?\nDùng ảnh khung đầu đã chuẩn bị ở bài 3 và prompt đã duyệt ở bài 4. Tải ảnh vào đúng ô, kiểm tra ảnh thu nhỏ rồi làm theo hướng dẫn của bước này. Không sao chép khung ví dụ này vào AI.',
      'EXAMPLE: IMAGE AND MOVEMENT\nImagine an image of Lan standing in front of the bench. You want the video to start from that picture, then show her taking two steps.\n\n- The image of Lan by the bench → goes in the starting-frame slot.\n- “Lan takes two steps and stops” → describes the movement; you wrote the prompt in Module 4.\n- Expected result → the video starts with Lan where the image places her, then she moves. This is a planned example, not a generated video.\n\nWHAT SHOULD YOU DO NOW?\nUse the starting image prepared in Module 3 and the prompt approved in Module 4. Upload the image to the correct slot, check the thumbnail and follow this step’s instructions. Do not paste this example box into AI.',
    ),
    tool: 'Seedance 2.5',
    save: t('Không cần tạo file ở bước này.', 'No file needed for this step.'),
  };

  references.steps.unshift(
    s(['Chọn ảnh chuẩn cho khuôn mặt trước khi tạo góc mới', 'Pick the reference image that decides the face before you make new views'], ['Ảnh chân dung là chuẩn cho khuôn mặt; ảnh toàn thân giữ tỷ lệ cơ thể, trang phục và ba lô; bảng nhiều góc chỉ dùng để kiểm tra. Bảng không phải là ảnh đầu của video. Hãy dùng các ảnh mẫu tải riêng bên dưới (bộ ZIP đầy đủ nằm ở bài 7, dành cho học viên đã đăng ký hoặc khi khóa được mở công khai toàn bộ) để so sánh: đường chân tóc, dáng mặt, mắt, bím tóc, cổ áo và dây ba lô. Chỉ giống màu thôi thì chưa đủ nếu người trong ảnh đã khác. Mỗi góc mới đều phải làm lại từ ảnh chuẩn gốc; đừng nối tiếp từ những ảnh đã lệch dần rồi lấy chúng làm chuẩn mới.', 'The portrait is the reference for the face; the full-body view sets proportions, clothing and the backpack; the multi-view sheet is only for checking. A sheet is not a starting frame for video. Use the individual sample downloads below (the full ZIP is in Module 7, for enrolled learners or when the course is fully public) and compare the hairline, face shape, eyes, braid, collar and backpack straps. Matching colors is not enough if the person has changed. Make every new angle from the original reference image, rather than chaining one drifting image after another and treating the latest as the new reference.'], '01-character/reference-qa.txt', undefined, 'planning', [
      'DUYỆT / SỬA / CHƯA RÕ\nMặt và đường tóc: cùng người?\nMột bím tóc, không thành hai?\nÁo vàng mù tạt, quần xanh than, giày nâu?\nBa lô xanh rêu; dây đeo đúng?\nTay/chân đủ, không dính vật?\nKhông chữ, logo, người thứ hai?\nGóc khuất không thể xác nhận: ghi “chưa rõ”, không đoán.\nLỗi nghiêm trọng → sửa ảnh trước. Sai ánh sáng nhẹ → cân nhắc mức nhìn thấy ở cỡ cảnh thực tế.',
      'ACCEPT / REPAIR / UNCLEAR\nSame face and hairline?\nExactly one braid?\nMustard jacket, navy trousers, brown shoes?\nMoss-green backpack with correct straps?\nIntact hands/feet without fused objects?\nNo text, logos or extra person?\nOccluded detail cannot be verified: mark unclear rather than guess.\nMajor identity/anatomy defect → repair the image first. Minor light variation → assess visibility at the actual shot size.',
    ], 'Codex · GPT Image'),
  );
  references.steps.push(s(['Luyện kiểm tra ảnh thay vì chỉ chọn ảnh đẹp nhất', 'Practice rejecting a beautiful image that does not fit'], ['Đặt ảnh chân dung và bảng góc nhìn cạnh nhau để so sánh. Ghi chú ba đặc điểm chắc chắn đã được giữ và một đặc điểm bạn chưa chắc. Góc nhìn từ phía sau không thấy mặt, nên chỉ từ góc đó thì chưa kết luận được là nhân vật đã đúng. Kiểm tra file lan-full.png bạn đã lưu ở bước trước, và chắc rằng nó không dính viền hay ô bên cạnh. Khi nhờ GPT Image sửa, hãy nói rõ vùng bị sai và những phần phải giữ nguyên; lưu bản mới là v02, đừng ghi đè lên v01. Mục tiêu là bạn giải thích được vì sao mình nhận ảnh hay yêu cầu sửa; bạn không cần bịa ra một lỗi không có chỉ để điền cho đủ phiếu.', 'Place the portrait and the view sheet side by side. Note three features that were clearly kept and one that you are unsure about. A view from behind hides the face, so it cannot prove on its own that the character is right. Check the lan-full.png you saved in the previous step, and make sure it contains no borders or neighboring panels. When you ask GPT Image for a repair, say which area is wrong and which parts must stay the same; save the new version as v02 instead of overwriting v01. The aim is to explain why you accepted an image or asked for a repair. Do not invent a defect just to fill in the worksheet.'], '01-character/reference-qa.txt + lan-full.png', undefined, 'planning', undefined, 'Codex · GPT Image'));

  planning.steps.unshift(s(['Vẽ sơ đồ địa điểm và trục hành động (đường nối Lan với ghế)', 'Draw the layout and the action axis (the line from Lan to the bench)'], ['Trước khi tạo một góc khác, hãy ghi lại: chiếc ghế nằm sát vách bên phải, cái cây ở bên trái lối vào, con đường đi xuống thung lũng, và lối Lan đi tới ghế. Sau đó vẽ nhìn từ trên xuống: chòi là một hình chữ nhật, ghế là một nét sát vách, Lan là một chấm, và mũi tên là đường đi. Đường nối từ Lan tới ghế gọi là trục hành động. Đặt camera A ở một phía của trục này; camera B ở cùng phía đó nhưng gần hơn. Nếu bạn đặt máy sang phía đối diện, hướng chuyển động trên màn hình có thể bị đảo. Sơ đồ này chỉ là cách bạn sắp xếp cảnh quay, không phải bản đo đạc chính xác dựng lại từ một ảnh AI.', 'Before you generate another angle, write down where things are: the bench against the right wall, the tree to the left of the opening, the path down to the valley, and the route Lan takes to the bench. Then sketch it from above: a rectangle for the shelter, a line for the bench, a dot for Lan and an arrow for her path. The line from Lan to the bench is called the action axis. Put camera A on one side of that axis, and camera B on the same side but closer. If you move the camera to the opposite side, movement on screen can reverse direction. This sketch is a way to plan your shots; it is not an accurate measured drawing rebuilt from an AI image.'], '02-location/floorplan.txt', undefined, 'planning', ['TRỤC: Lan → ghế\nCamera A: toàn cảnh, thấy cả đường tới ghế\nCamera B: trung cảnh, cùng phía trục\nĐèn: trên ghế phải; tắt → sáng → giữ sáng\nHướng mắt shot 3: tới đường xuống thung lũng\nMốc bất biến: ghế/vách, cây/cửa, đường/thung lũng\nKiểm tra từng góc: mốc còn hợp lý? nhân vật có chỗ bước?', 'AXIS: Lan → bench\nCamera A: wide, full route to bench visible\nCamera B: medium, same side of axis\nLantern: on right bench; unlit → lit → stays lit\nShot 3 eyeline: toward valley path\nAnchors: bench/wall, tree/opening, path/valley\nCheck each view: are anchors consistent and is there room to step?'], t('Giấy bút / công cụ vẽ', 'Paper / drawing tool')));
  const compose = planning.steps.find(step => step.prompt === seedanceCoursePrompts.startFrame[1]);
  if (compose) compose.instruction = t('Cách dùng bốn ảnh: tải ảnh chân dung, lan-full.png, location-master.png và lantern-off.png theo đúng thứ tự này, rồi dùng prompt bên dưới. Nếu công cụ chỉ nhận ba hoặc hai ảnh, hãy làm bài tùy chọn “Ghép khi thiếu ô tải” trước; KHÔNG dùng prompt bốn ảnh với ba file. Kiểm tra xem kết quả có đúng một cảnh, một Lan, một chiếc đèn và lối đi tới ghế còn trống không. Chỉ ảnh đơn hoàn chỉnh mới được đưa vào ô khung hình đầu của video.', 'Four-image route: upload the portrait, lan-full.png, location-master.png and lantern-off.png in that order, then use the prompt below. If your tool accepts only three or two images, do the optional lab “Compose with fewer upload slots” first; do NOT use the four-image prompt with three files. Check that you have one scene, one Lan, one lantern and a clear route to the bench. Only the finished single frame goes into the video’s starting-frame slot.');
  planning.techniques = [...(planning.techniques || []), optional('sd25-fewer-inputs', ['Ghép khi thiếu ô tải', 'Compose with fewer upload slots'], ['Đổi cách phân bổ ảnh vào các ô tải lên và đổi prompt cùng lúc.', 'Change which image goes in which slot, and change the prompt at the same time.'], ['Chòi trống, chiếc đèn tắt, ảnh chân dung và ảnh toàn thân đã duyệt.', 'The approved empty shelter, unlit lantern, portrait and full-body view.'], [
    s(['Ghép chòi và đèn trước', 'Combine the shelter and the lantern first'], ['Tải chòi trống làm ảnh 1 và chiếc đèn tắt làm ảnh 2. Chạy yêu cầu dưới đây trong GPT Image. Duyệt kết quả khi chỉ có một chiếc đèn trên ghế, rồi lưu thành scene-with-lantern.png. Nếu chiếc đèn hoặc chiếc ghế bị sai thì dừng lại, đừng làm tiếp.', 'Upload the empty shelter as image 1 and the unlit lantern as image 2. Run the request below in GPT Image. Approve the result when there is exactly one lantern on the bench, and save it as scene-with-lantern.png. If the lantern or the bench is wrong, stop here and do not continue.'], '02-location/scene-with-lantern.png', p.sceneProp, 'image', undefined, 'Codex · GPT Image'),
    s(['Nhánh ba ảnh', 'Three-image branch'], ['Chỉ làm bước này khi giao diện nhận được ba ảnh: ảnh 1 là scene-with-lantern.png, ảnh 2 là ảnh chân dung, ảnh 3 là ảnh toàn thân. Dùng đúng prompt ba ảnh dưới đây. Nếu giao diện chỉ nhận hai ảnh, bỏ qua bước này và làm nhánh tiếp theo.', 'Do this step only if the interface accepts three images: image 1 = scene-with-lantern.png, image 2 = the portrait, image 3 = the full-body view. Use the three-image prompt below. If it accepts only two images, skip this step and use the next branch.'], '02-location/shot-01-start.png', p.composeThree, 'image', undefined, 'Codex · GPT Image'),
    s(['Nhánh hai ảnh', 'Two-image branch'], ['Ảnh 1 là scene-with-lantern.png, ảnh 2 là lan-full.png. Dùng prompt hai ảnh dưới đây. Đổi lại, khuôn mặt trong ảnh toàn thân có thể quá nhỏ: nếu không giữ được đúng mặt thì chọn một giao diện nhận thêm cả ảnh chân dung, hoặc dừng lại; đừng chấp nhận một ảnh mà khuôn mặt còn mơ hồ.', 'Image 1 = scene-with-lantern.png, image 2 = lan-full.png. Use the two-image prompt below. The trade-off is that the face in the full-body view may be too small: if the face cannot be kept right, use an interface that also accepts the portrait, or stop; do not approve an image where the face is unclear.'], '02-location/shot-01-start.png', p.composeTwo, 'image', undefined, 'Codex · GPT Image'),
  ], ['Số file khớp với mọi tham chiếu trong prompt; chỉ có một người, một chiếc đèn, và bố cục địa điểm được giữ đúng.', 'The number of files matches every reference in the prompt; there is one person, one lantern, and the layout of the place is unchanged.'], ['Quay lại scene-with-lantern và sửa ảnh trước khi đổi bất kỳ prompt video nào.', 'Go back to scene-with-lantern and fix the image before you change any video prompt.'])];

  frames.steps.unshift(s(['Hiểu từng phần trước khi sao chép prompt', 'Understand each part of a prompt before you copy it'], ['Một prompt tốt mô tả điều cần nhìn thấy theo thứ tự: vai trò của ảnh, trạng thái ban đầu, một hành động, camera, những điều phải giữ nguyên, điểm kết thúc và âm thanh. Không phải shot nào cũng cần đủ mọi câu. Hãy đặt thời lượng và độ phân giải ở giao diện; viết “8K masterpiece” không thay được các thiết lập đó. Chữ “cinematic” cũng không cho biết nhân vật làm gì. Dùng bảng giải thích dưới đây để tự bỏ những câu thừa và phát hiện hai chỉ dẫn mâu thuẫn nhau.', 'A useful prompt describes what you want to see, in order: the role of the image, the starting state, one action, the camera, what must stay the same, the ending and the sound. Not every shot needs every sentence. Set the duration and resolution in the interface; writing “8K masterpiece” does not replace those settings. The word “cinematic” does not tell the model what the character does. Use the explanation below to cut redundant sentences and to spot two instructions that contradict each other.'], '03-prompts/prompt-anatomy.txt', undefined, 'planning', [
    '“Dùng ảnh làm khung đầu” → neo bố cục ban đầu; không nói ảnh điều khiển toàn bộ chuyển động.\n“Lan bước hai bước nhỏ tới ghế rồi dừng” → nhân vật + hành động + điểm kết thúc.\n“Camera ngang mắt cố định” → loại một biến camera.\n“Giữ mặt, bím, áo và ba lô” → các đặc điểm cần kiểm tra.\n“Đèn tắt trên ghế” → trạng thái đạo cụ không được đổi.\n“Không thoại, nhạc hoặc chữ” → ý đồ âm thanh/chữ; vẫn kiểm tra đầu ra.\nGiao diện: 5 giây / 720p / 16:9 / âm thanh tắt nếu có.\nYếu: “phim cực đẹp, Lan đi, zoom mà camera đứng yên”.\nSửa: chọn camera cố định HOẶC tiến máy; mô tả đường đi và chỗ dừng.',
    '“Use the image as the starting frame” → anchors composition; does not claim control over all motion.\n“Lan takes two small steps toward the bench and stops” → subject + action + ending.\n“Fixed eye-level camera” → removes a camera variable.\n“Preserve face, braid, jacket and backpack” → identifies inspection targets.\n“Lantern stays unlit on the bench” → preserves prop state.\n“No dialogue, music or text” → sound/text intent; still inspect outputs.\nInterface: 5 seconds / 720p / 16:9 / audio off if available.\nWeak: “beautiful cinematic film, Lan walks, zoom while the camera stays still.”\nRepair: choose a fixed view OR a push-in; specify route and stopping point.',
  ]));
  frames.steps.push(s(['Tự viết rồi nhờ ChatGPT/Claude phản biện', 'Draft first, then ask ChatGPT/Claude to critique it'], ["Hãy tự viết một prompt dài 40-90 từ cho cùng bức ảnh, nhưng đổi hành động thành Lan nhìn xuống chiếc đèn. Gạch chân câu chỉ nói về hành động và câu chỉ nói về camera. Gửi ảnh cùng bản brief cho ChatGPT hoặc Claude kèm yêu cầu dưới đây. So sánh hai bản: trợ lý có tự thêm gió, lời thoại, chuyển động camera hay file nào không? Với từng đề xuất, quyết định giữ hay bỏ và ghi lý do. Làm việc độc lập nghĩa là bạn hiểu và chịu trách nhiệm về các lựa chọn của mình; bạn vẫn được dùng trợ lý.", "Write your own 40-90-word prompt for the same image, but change the action to Lan looking down at the lantern. Underline the sentence that describes only the action and the sentence that describes only the camera. Send the image and your brief to ChatGPT or Claude with the request below. Compare the two versions: did the assistant add wind, speech, camera movement or files that you did not ask for? For each suggestion, decide whether to keep or reject it and write down why. Working independently means that you understand your choices and take responsibility for them; you are still allowed to use an assistant."], '03-prompts/my-draft-and-revision.txt', p.assistantTutor));

  frames.steps.push(s(['Một trao đổi thật với Claude và lượt biên tập của Codex', 'A real exchange with Claude, and the edit Codex made'], ['Bản brief gửi cho Claude Code chỉ có chữ: một ảnh đã duyệt, Lan ở lối vào, chiếc đèn tắt trên ghế, hai bước nhỏ về phía ghế rồi dừng, máy quay cố định, 5 giây/720p/16:9. Claude KHÔNG xem ảnh và không chạy Seedance. Bên dưới là bản dịch tiếng Việt của đoạn prompt thật; bản gốc tiếng Anh được lưu trong hồ sơ biên tập của khóa. Codex đã kiểm tra những phần trợ lý tự thêm và sửa cho khớp với brief. Đây là bằng chứng cho việc tạo chữ, không phải bằng chứng cho việc tạo video.', 'The text-only brief sent to Claude Code described one approved frame, Lan at the entrance, an unlit lantern on the bench, two steps toward the bench and a stop, a fixed camera, and 5 seconds/720p/16:9. Claude did NOT see the image and did not run Seedance. Below is the actual excerpt of its prompt; the full request and response are kept in the course’s editorial records. Codex checked what the assistant had added and edited the prompt to match the brief. This is evidence that the text was generated; it is not evidence that any video was generated.'], '03-prompts/assistant-comparison.txt', undefined, 'planning', [
    'CLAUDE — bản dịch do GenYZ biên tập từ đầu ra tiếng Anh:\nBắt đầu từ ảnh cung cấp làm khung đầu, Lan đứng ở lối vào chòi với áo vàng mù tạt và ba lô xanh rêu. Cô bước hai bước nhỏ, chậm tới ghế bên phải, rồi dừng và đứng yên, hướng về đèn tắt. Camera cố định, không di chuyển. Đèn giữ tắt và nằm yên trên ghế. Áo, ba lô và chòi giữ như khung đầu. Không thoại, không nhạc.\n\nCODEX BIÊN TẬP:\n1. “Chậm” và “hướng về đèn” là phần thêm; bỏ nếu không cần vì có thể đổi nhịp hoặc thêm xoay người.\n2. Tự giải thích từng câu thật thay vì chỉ tin nhãn trợ lý đặt.\n3. Yêu cầu “giữ nguyên” chỉ là ý định, vẫn phải kiểm tra.\n4. Dùng prompt clip ngắn ở bài 5 cho lần chạy; chỉ sao chép một ngôn ngữ.\nThử tự làm: giữ một đề xuất, bỏ một đề xuất và giải thích lý do.',
    `CLAUDE — actual English output excerpt (${assistantExample.model}):\n${assistantExample.prompt}\n\nCODEX EDITORIAL REVIEW:\n1. “Slow” and “facing the unlit lantern” were additions; remove them if unnecessary because they can change pacing or add a turn.\n2. Explain every actual clause rather than trusting an assistant’s labels.\n3. “Stay exactly” expresses intent and still needs output inspection.\n4. Use the short clip prompt in Module 5 for the run; copy one language only.\nYour exercise: retain one suggestion, reject another, and explain why.`,
  ], 'Claude Code → GPT Codex'));

  motion.steps.unshift(s(['Chuyển động của camera và của nhân vật là hai việc khác nhau', 'Camera movement and character movement are two separate things'], ['Chọn cỡ cảnh theo điều người xem cần thấy, rồi quyết định camera có di chuyển hay không.', 'Choose the shot size for what the viewer needs to see, then decide whether the camera should move.'], '03-prompts/camera-decisions.txt', undefined, 'planning', ['Cảnh đi tới ghế: toàn cảnh, máy cố định, thấy bàn chân.\nĐèn sáng: giữ cỡ cảnh cuối shot 1, thấy Lan ở chỗ dừng thực tế và đọc được đèn; máy cố định, thấy ánh sáng đổi. Cận đèn là shot riêng, cần khung đầu riêng.\nNhận ra đường về: trung cảnh, giữ hướng mắt.\nThử nâng cao: giữ người đứng yên, chỉ thêm tiến máy.\nCâu hỏi: xem ở kích thước điện thoại có hiểu hành động không?', 'Approach the bench: wide, fixed camera, feet visible.\nLantern glows: keep shot 1 ending framing, Lan at her actual stopping position and lantern readable; fixed camera, visible light change. A close insert is a separate shot with its own starting frame.\nRecognize the way home: medium, consistent eyeline.\nAdvanced test: stationary subject, add only a push-in.\nQuestion: is the action understandable on a phone-sized display?']));
  motion.steps[1].instructionPoints = firstFrameGuide.instructionPoints;
  motion.steps[1].resultTitle = firstFrameGuide.resultTitle;
  motion.steps[1].resultText = firstFrameGuide.resultText;
  motion.steps[0].instructionPoints = locale === 'vi' ? [
    'Toàn cảnh (wide shot): cho thấy nơi chốn, vị trí nhân vật và đường đi. Ví dụ: thấy cả Lan, chiếc ghế và khoảng cách cô cần bước tới.',
    'Trung cảnh (medium shot): thường lấy nhân vật từ khoảng thắt lưng trở lên, để thấy cử chỉ tay và thân người.',
    'Cận cảnh (close-up): tập trung vào nét mặt hoặc một chi tiết, chẳng hạn khuôn mặt Lan hay chiếc đèn trên ghế.',
    'Máy cố định (static shot): camera giữ nguyên vị trí và hướng nhìn. Lan bước đi trong khung hình khác với Lan đứng yên còn camera tiến lại gần.',
    'Lia ngang (pan): camera xoay sang trái hoặc phải tại chỗ, giống như bạn quay đầu để nhìn theo một người.',
    'Di chuyển máy (dolly): camera đổi vị trí trong không gian. Khi tiến lại gần (dolly-in), khoảng cách giữa camera và nhân vật giảm; vật ở gần và ở xa thay đổi vị trí tương đối trong khung hình.',
    'Thay đổi độ phóng đại (zoom): camera giữ nguyên vị trí, nhưng khung hình thu hẹp hoặc mở rộng. Nhân vật có thể trông lớn hơn mà camera không cần tiến lại gần.',
    'Với shot đầu tiên, chọn một hành động dễ kiểm tra: Lan bước hai bước, camera cố định. Khi đã làm được, thử riêng một chuyển động máy để dễ nhận ra tác động của nó.',
    'Cỡ cảnh (shot size) mô tả phần hình ảnh bạn muốn thấy. Tiêu cự (focal length), chẳng hạn 35 mm hay 85 mm, chỉ là gợi ý cho công cụ AI; ghi con số không bảo đảm mô phỏng đúng ống kính thật.',
  ] : [
    'Wide shot: shows the setting, the character’s position and their route. For example, show Lan, the bench and the distance she needs to walk.',
    'Medium shot: usually frames the character from around the waist up, making hand and body gestures readable.',
    'Close-up: focuses on an expression or detail, such as Lan’s face or the lantern on the bench.',
    'Static shot: the camera stays in the same position and points in the same direction. Lan walking through the frame differs from Lan standing still while the camera moves closer.',
    'Pan: the camera turns left or right from a fixed position, like turning your head to follow someone.',
    'Dolly: the camera changes position in space. A dolly-in brings it closer to the character; nearby and distant objects shift relative to each other in the frame.',
    'Zoom: the camera stays in place while the view becomes tighter or wider. The character can appear larger without the camera moving closer.',
    'For your first shot, choose one action you can check: Lan takes two steps while the camera stays still. Once that works, try one camera movement separately so you can see its effect.',
    'Shot size describes how much of the scene you want to show. A focal length such as 35 mm or 85 mm is only guidance for the AI tool; a number does not guarantee an accurate lens simulation.',
  ];

  motion.checks[0] = t('Đường video: tôi đã lưu một clip hoặc một đoạn dùng được. Đường chuẩn bị: tôi đã lưu prompt, ảnh và một nhật ký ghi “video chưa thử”; tôi chưa cho rằng mình đã có kỹ năng tạo video.', 'Video path: I saved a clip or a usable segment. Preparation path: I saved my prompts, my images and a log marked “video untested”; I have not claimed that I can generate video.');
  motion.steps.push(s(['Tìm nguyên nhân và chọn cách sửa rẻ nhất mà có tác dụng', 'Find the cause and choose the cheapest repair that helps'], ['Dùng bảng dưới đây trước khi tạo thêm. Hãy phân biệt lỗi đã có sẵn trong đầu vào với lỗi chỉ xuất hiện theo thời gian. Xem ở tốc độ bình thường trước, rồi mới xem từng khung hình để tìm ra lúc lỗi bắt đầu. Mỗi lần thử chỉ đổi một thứ, để bạn biết điều gì có tác dụng. Bài này cho phép tối đa ba lần thử; đó là mức trần, không phải lời hứa rằng ba lần là đủ để đạt. Khi hết ngân sách thì dừng: giữ lại đoạn tốt, dùng ảnh tĩnh, hoặc đơn giản hóa cách kể. Đừng chi thêm chỉ vì bạn đã chi nhiều.', 'Use the table below before you generate again. Separate defects that were already in the input from defects that only appear over time. Watch at normal speed first, then go through the frames to find where the problem starts. Change only one thing per attempt, so you can tell what made the difference. This exercise allows up to three attempts at most; that is a ceiling, not a promise that three will be enough. When you reach your budget, stop: keep a good segment, use a still image, or simplify the story. Do not spend more just because you have already spent a lot.'], '04-clips/diagnosis.txt', p.diagnosis, 'planning', [
    'TRIỆU CHỨNG → KIỂM TRA → MỘT CÁCH SỬA\nMặt sai từ khung đầu → ảnh chuẩn/ô tải → sửa ảnh hoặc ô, chưa đổi motion.\nMặt trôi khi quay đầu → biên độ quay/che khuất → giảm biên độ hoặc đổi cỡ cảnh.\nChân trượt → khoảng cách/nhịp/sàn → rút đường đi; kiểm tra lại clip.\nGhế méo khi máy chạy → hình học + parallax → thử máy cố định.\nĐèn tự sáng quá sớm → trạng thái đầu/cuối → tách shot đèn.\nHành động bị cắt giữa → nhiều nhịp/thời lượng → bỏ một nhịp trước khi kéo dài.\nNối cảnh giật → khung cuối/đầu → cắt tại khung sạch hoặc sửa ảnh nối.\nKhông chắc nguyên nhân → ghi giả thuyết; không khẳng định lỗi do prompt.\nCác dòng trên là tình huống giảng dạy, chưa phải lỗi video đã quan sát trong khóa.',
    'SYMPTOM → CHECK → ONE REPAIR\nWrong face from frame one → reference/upload role → fix image or slot before motion.\nIdentity drifts during a turn → turn amplitude/occlusion → reduce turn or change framing.\nSliding feet → distance/timing/floor → shorten travel; inspect again.\nBench warps during camera motion → geometry/parallax → test a fixed camera.\nLantern lights too early → start/end state → separate the lantern shot.\nAction ends halfway → beat count/duration → remove a beat before extending.\nJump at a cut → outgoing/incoming frame → cut on a clean frame or repair the join.\nUncertain cause → record a hypothesis; do not assert the prompt caused it.\nThese are authored teaching scenarios, not observed course video failures.',
  ]));
  motion.techniques = [...(motion.techniques || []),
    optional('sd25-camera-ab', ['So sánh camera A/B', 'Camera A/B comparison'], ['Thấy được tác động của riêng một yếu tố.', 'See the effect of changing just one thing.'], ['Một ảnh Lan đứng yên và ngân sách cho tối đa hai take.', 'One image of Lan standing still, and a budget for at most two takes.'], [s(['Giữ A cố định, chỉ cho máy tiến vào ở B', 'Keep A fixed, and only move the camera forward in B (a push-in)'], ['A: người đứng yên, máy cố định. B: cùng ảnh, cùng thời lượng, độ phân giải, nhân vật và ánh sáng; dùng prompt tiến máy bên dưới. Ghi báo giá của cả hai trước khi tạo. So sánh đầu, giữa và cuối của từng bản: kích thước của Lan, vật gần và vật xa, chiếc ghế có bị méo không, khuôn mặt. Kết quả AI có tính ngẫu nhiên; một cặp take chỉ là bằng chứng hẹp, không chứng minh một quy luật chung. Nếu hết credit: viết ra những dự đoán của bạn và ghi chưa chạy.', 'A: the character stands still and the camera is fixed. B: the same image, duration, resolution, character and lighting; use the push-in prompt below. Write down both quotes before you generate. Compare the start, middle and end of each one: the size of Lan, near and distant objects, whether the bench warps, and the face. AI results vary from run to run, so one pair of takes is only narrow evidence and does not prove a general rule. If you have no credits left, write down your predictions and mark the lab as not run.'], '04-clips/camera-ab.txt', p.cameraPush, 'video', undefined, 'Seedance 2.5')], ['Giải thích được camera thật sự di chuyển hay chỉ phóng to ảnh, dựa trên từng take; hoặc ghi rõ là chưa chạy.', 'You can explain whether the camera really moved or the image was just magnified, using what you saw in each take, or you clearly mark the lab as not run.'], ['Nếu bạn đổi cả nhân vật, camera và thời lượng cùng lúc, hãy lập lại phép so sánh sao cho chỉ đổi camera.', 'If you changed the character, the camera and the duration all at once, redo the comparison so that only the camera changes.']),
    optional('sd25-draft-final', ['Bản nháp chính thức, tạo lại và upscale', 'Draft and finalize, regenerate, or upscale'], ['Chọn đúng quy trình để hoàn thiện clip, không lẫn lộn các kết quả khác nhau.', 'Choose the right way to finish a clip, without confusing the different outcomes.'], ['Một tài khoản có nút Draft/finalize, hoặc chỉ có tùy chọn độ phân giải.', 'An account that has a Draft/finalize control, or only a resolution option.'], [s(['Kiểm tra xem bản hoàn thiện có liên kết với bản nháp không', 'Check whether finalizing is linked to a draft'], ['Trong cấu hình Higgsfield mà khóa đã quan sát, draft=true tạo bản nháp 480p, còn draft_job_id tham chiếu tới một job nháp đã xong để hoàn thiện thành 1080p, với thời hạn được ghi là 7 ngày. Đây là tên trường của công cụ, không phải chữ để dán vào giao diện. Chỉ dùng cách này khi giao diện và tài khoản của bạn thật sự có; hãy ghi lại job, thời hạn, báo giá và kết quả. Nếu bạn chỉ đổi độ phân giải rồi bấm Generate, đó là một lần tạo mới. Upscale chỉ phóng lớn clip đã có; nó không tự sửa hành động, giải phẫu cơ thể hay khuôn mặt. Kể cả khi bản hoàn thiện có liên kết với bản nháp, bạn vẫn phải xem lại toàn bộ trước khi dùng.', 'In the Higgsfield configuration we observed, draft=true makes a 480p draft, and draft_job_id points to a finished draft job so that it can be finalized at 1080p, with a stated window of 7 days. These are the tool’s field names, not text to paste into the interface. Use this only if your interface and account actually offer it; record the job, the deadline, the quote and the result. If you only change the resolution and press Generate, that is a new generation. Upscaling just enlarges a clip you already have; it does not repair the action, the anatomy or the face. Even when finalizing is linked to a draft, review the whole clip before you use it.'], '04-clips/finalization-decision.txt', undefined, 'planning', ['QUY TRÌNH / JOB GỐC / JOB MỚI / HẠN / GIÁ / KHÁC BIỆT / QUYẾT ĐỊNH\nDraft → finalize: có liên kết job thật?\nRegenerate: có thay chuyển động không?\nUpscale: chi tiết rõ hơn hay lỗi cũng lớn hơn?\nKhông có tính năng: ghi không khả dụng, không tự tạo tên nút.', 'WORKFLOW / SOURCE JOB / NEW JOB / DEADLINE / PRICE / DIFFERENCE / DECISION\nDraft → finalize: is there an actual job link?\nRegenerate: did movement change?\nUpscale: clearer details or enlarged defects?\nUnavailable feature: record unavailable rather than inventing a button.'], 'Seedance 2.5 / ' + t('công cụ upscale', 'upscale tool'))], ['Gọi đúng tên quy trình mình đã dùng và xem lại bản cuối.', 'Name the workflow you actually used, and review the final result.'], ['Nếu không thấy nút finalize: giữ bản nháp nếu chất lượng đã đủ, hoặc dự trù ngân sách cho một lần tạo mới.', 'If you cannot find a finalize control: keep the draft if its quality is good enough, or budget for a new generation.']),
  ];

  review.steps.unshift(s(['Nối trạng thái của cảnh, không chỉ nối các file', 'Connect the state of the scene, not just the files'], ['Lập bảng trạng thái trước khi tạo shot tiếp theo. Khung cuối dùng để nối phải nằm đúng ở điểm bạn cắt; nếu bạn đã bỏ đoạn cuối của file thì đừng lấy khung cuối cùng của file. Giữ chiếc đèn tắt suốt shot 1, sáng lên trong shot 2 và vẫn sáng ở shot 3. Nếu bạn học theo đường chuẩn bị, hãy dùng ba ảnh đã duyệt làm storyboard hoặc animatic, điền bảng bên dưới, bỏ qua các bước cần clip thật và chuyển sang bài 7. Ghi rõ các trạng thái là “dự kiến”: chuyển động và việc nối video vẫn chưa được chứng minh.', 'Write a state table before you generate the next shot. The ending frame you use for the join must be the frame at your actual cut point; if you trimmed away the end of the file, do not use the last frame of the file. Keep the lantern unlit through shot 1, lighting up in shot 2 and still lit in shot 3. If you are on the preparation path, use three approved still images as a storyboard or animatic, fill in the table below, skip the steps that need real clips, and go on to Module 7. Mark the states as “planned”: movement and video continuity are still unproven.'], '04-clips/continuity.tsv', undefined, 'planning', [
    'SHOT / ĐẦU / HÀNH ĐỘNG / CUỐI / ĐÈN / HƯỚNG / FILE NỐI\n01 / Lan ở lối vào / bước tới ghế rồi dừng / vị trí dừng thực tế / tắt / tới phải / khung tại điểm cắt\n02 / vị trí cuối shot trước / đèn sáng, Lan nhìn xuống / giữ nguyên vị trí / sáng / nhìn xuống / khung tại điểm cắt\n03 / vị trí cuối shot trước / nhìn ra đường / giữ ánh nhìn / vẫn sáng / tới đường / khung kết\nKiểm tra hai phía điểm cắt: vị trí tay/chân, độ cao camera, ánh sáng, màu áo và trạng thái đèn.\nNếu đổi sang cận đèn: không yêu cầu thấy toàn thân Lan trong cùng shot.',
    'SHOT / START / ACTION / END / LANTERN / DIRECTION / JOIN FILE\n01 / Lan at entrance / approaches bench and stops / actual stopping position / unlit / toward right / frame at edit point\n02 / previous ending position / lantern glows, Lan looks down / same position / lit / down / frame at edit point\n03 / previous ending position / looks toward path / holds gaze / still lit / toward path / ending frame\nCheck both sides of each cut: hands/feet, camera height, light, jacket color and lantern state.\nFor a lantern insert, do not also demand Lan’s full body within the same shot.',
  ], 'CapCut / ' + t('sổ thực hành', 'workbook')));
  review.input = t('Clip shot 1 đã duyệt, hoặc ba ảnh tĩnh nếu bạn học theo đường chuẩn bị. Cả hai đường đều cần một bảng trạng thái và các ảnh chuẩn.', 'An approved shot 1 clip, or three still images if you are on the preparation path. Both paths need a state table and the reference images.');
  review.checks = [t('Tôi đã lập bảng trạng thái tắt → sáng → vẫn sáng và kiểm tra hai phía của mỗi chỗ nối.', 'I mapped out unlit → lit → stays lit and checked both sides of every join.'), t('Đường video: tôi có các clip và khung nối lấy đúng tại điểm cắt. Đường chuẩn bị: tôi có một animatic và ghi rõ video chưa thử.', 'Video path: I have the clips and join frames taken at the actual cut points. Preparation path: I have an animatic and I label the video as untested.'), t('Tôi giải thích được một quyết định dựng, và phân biệt được việc đổi cỡ cảnh với việc đổi địa điểm.', 'I can explain one editing decision, and I can tell a change of framing from a change of location.')];
  review.techniques = [...(review.techniques || []),
    optional('sd25-modes', ['Text-to-video, omni reference và hai khung đầu/cuối', 'Text-to-video, omni reference and first/last frames'], ['Biết mỗi mode cho bạn điều khiển được điều gì, và chọn đúng đầu vào.', 'Know what each mode lets you control, and pick the right inputs.'], ['Ảnh tham chiếu Lan và địa điểm, cùng hai trạng thái có góc máy và bố cục khớp nhau; ngân sách do bạn tự đặt.', 'Reference images of Lan and the location, and two states that share the same camera and layout; a budget you set yourself.'], [
      s(['So sánh cách hoạt động của từng mode trước khi tiêu credit', 'Compare how each mode works before you spend credits'], ['Text-to-video (T2V) chỉ dùng chữ: dùng để khám phá ý tưởng khi việc giữ đúng nhân vật không quá quan trọng, và ghi lại rằng Lan có thể khác ảnh chuẩn. Với omni reference: chọn chế độ nhiều tham chiếu nếu có, tải ảnh chân dung, ảnh toàn thân và ảnh chòi, rồi lập bảng tên file và vai trò của từng file. Nếu giao diện tự tạo thẻ, hãy chèn thẻ bằng bộ chọn của giao diện và kiểm tra từng thẻ có đúng file không; đừng gõ @Image1 khi trang không dùng thẻ. Bỏ bớt những tham chiếu trùng lặp hoặc mâu thuẫn, đừng tải lên nhiều phiên bản khuôn mặt không khớp nhau. Chỉ cần chọn một mode để chạy; bạn không phải trả tiền cho cả ba.', 'Text-to-video (T2V) uses text alone: use it to explore an idea where keeping the exact character matters less, and note that Lan may look different from your approved portrait. For omni reference, choose a multi-reference mode if there is one, upload the portrait, the full-body view and the shelter, and write a table of each filename and its role. If the interface creates tags, insert them through its picker and check that each tag points to the right file; do not type @Image1 into an interface that has no tags. Remove references that repeat or contradict one another, and do not upload several versions of the face that do not match. Pick just one mode to run; you do not have to pay for all three.'], '04-clips/mode-comparison.txt', p.omni, 'video', undefined, 'Seedance 2.5'),
      s(['Nối hai tư thế khớp nhau', 'Connect two poses that fit together'], ['Dùng GPT Image tạo ảnh cuối từ ảnh đầu: chỉ đổi hướng đầu của Lan, giữ nguyên camera, chiếc ghế, chiếc đèn đã sáng và đôi chân. Nếu nhà cung cấp hỗ trợ, đặt ảnh đầu và ảnh cuối vào đúng hai ô đầu/cuối. Chỉ dùng prompt bên dưới khi chiếc đèn trong CẢ HAI ảnh đã sáng. Hãy xem cả đường chuyển động ở giữa, không chỉ hai đầu: phần giữa có bị biến dạng không? Nếu hai ảnh khác nhau quá nhiều về góc máy và bố cục, thường nên sửa ảnh hoặc cắt dựng, đừng ép model tự nối.', 'In GPT Image, create an end frame from the start frame: change only the direction of Lan’s head, and keep the camera, the bench, the lit lantern and her feet the same. If the provider supports it, put the start image and the end image into the first and last slots. Use the prompt below only when the lantern is already lit in BOTH images. Look at what happens between the two ends, not just at the ends themselves: does the middle of the clip warp? If the two images differ a lot in camera angle and layout, it is usually better to repair the images or to make an ordinary cut in the edit than to force the model to join them.'], '02-location/endpoint-first.png + endpoint-last.png + 04-clips/endpoints-review.txt', p.endpoints, 'video', undefined, 'GPT Image → Seedance 2.5'),
    ], ['Nêu được mode đã dùng, vai trò của từng file và giới hạn của nó; hai ảnh đầu và cuối đúng thôi thì chưa đủ để coi cả clip là đạt.', 'You can name the mode, the role of each file and its limits; having correct first and last images is not enough to pass the whole clip.'], ['Nếu các đầu vào mâu thuẫn nhau: bỏ file sai, hoặc sửa ảnh đầu/cuối trước khi thêm chữ vào prompt.', 'If the inputs contradict each other: remove the wrong file, or repair the first and last images before you add more words to the prompt.']),
    optional('sd25-long-extension', ['Nhiều shot trong một lần tạo, và kéo dài một clip', 'Several shots in one generation, and extending a clip'], ['Cân nhắc giữa một lần tạo dài và việc kiểm soát từng shot riêng.', 'Weigh one long generation against controlling each shot separately.'], ['Kế hoạch ba shot, hoặc một clip có đoạn kết sạch; một chế độ được hỗ trợ và báo giá.', 'A three-shot plan, or a clip with a clean ending; a supported mode and a quote.'], [
      s(['Thử một chuỗi nhiều shot có chủ đích', 'Plan a multi-shot sequence on purpose'], ['Dùng kế hoạch ba shot bạn đã có và chọn một thời lượng mà giao diện cho phép. Hãy phân biệt một video gồm nhiều cú cắt với một cú máy liên tục: prompt bên dưới yêu cầu ba shot. Phân bổ thời gian trước, ví dụ 5 + 4 + 5 giây nếu giao diện hỗ trợ 14 giây. Ghi dự kiến chi phí, và chỉ chạy khi bạn chấp nhận rủi ro phải bỏ cả một đoạn dài. Kiểm tra số shot, thứ tự hành động, nhân vật, trạng thái chiếc đèn và các điểm cắt. Dòng “hỗ trợ tối đa 30 giây” không bảo đảm mọi clip dài đều liền mạch.', 'Use your three-shot plan and choose a duration the interface allows. Keep two things apart: a video with several cuts, and one continuous take. The prompt below asks for three shots. Divide the time first, for example 5 + 4 + 5 seconds if 14 seconds is supported. Write down the expected cost, and run it only if you accept the risk of throwing away a long segment. Check the number of shots, the order of actions, the character, the state of the lantern and the cuts. A line like “supports up to 30 seconds” does not guarantee that every long clip will hold together.'], '04-clips/long-sequence-review.txt', p.sequence, 'video', undefined, 'Seedance 2.5'),
      s(['Kéo dài từ trạng thái cuối thật', 'Extend from the real ending state'], ['Chọn video_extension, hoặc nút tương đương nếu có. Tải clip gốc lên, chọn hướng forward/after khi được hỏi, rồi ghi lại thời lượng phần thêm và giá. Prompt bên dưới cần một clip kết thúc cạnh chiếc ghế với chiếc đèn ĐÃ sáng; đừng dùng nó cho shot 1, nơi đèn còn tắt. So sánh hai phía của chỗ nối về camera, tốc độ, tư thế, chiếc đèn và âm thanh. Hãy phân biệt việc kéo dài từ video với việc lấy một khung cuối làm ảnh đầu cho một job mới. Nếu không có tính năng kéo dài, dùng cách khung cuối ở phần bài chính và gọi đúng tên cách đó.', 'Choose video_extension, or the equivalent control if there is one. Upload the source clip, pick forward/after when you are asked, and write down the added duration and the price. The prompt below needs a clip that ends beside the bench with the lantern ALREADY lit; do not use it on shot 1, where the lantern is unlit. Compare both sides of the seam for camera, speed, pose, lantern and sound. Keep video extension apart from taking an ending still and using it as the first frame of a new job. If extension is not available, use the ending-frame method from the main exercise and call it by its proper name.'], '04-clips/extension-log.txt', p.extension, 'video', undefined, 'Seedance 2.5'),
    ], ['Lưu clip gốc, phần được thêm và bản đánh giá chỗ nối; ghi rõ những tính năng chưa có hoặc chưa chạy.', 'Save the source clip, the added part and your review of the seam; clearly mark any feature that is unavailable or not run.'], ['Nếu chỗ nối hỏng, hãy sửa điểm kết thúc hoặc chọn một cú cắt có chủ đích; đừng kéo dài một lỗi đang có.', 'If the seam fails, repair the ending or choose a deliberate cut; do not extend a defect.']),
    optional('sd25-native-edit', ['Sửa video theo khoảng thời gian và đổi góc nhìn', 'Editing a video by time range, and changing the viewpoint'], ['Giới hạn phạm vi sửa, rồi kiểm tra cả những phần lẽ ra phải giữ nguyên.', 'Limit the scope of an edit, then check the parts that should have stayed the same.'], ['Video của bạn, ảnh tham chiếu và mốc thời gian của lỗi; một mode sửa video thực sự có trong công cụ.', 'Your own video, a reference image and the timestamps of the defect; a video-edit mode that actually exists in your tool.'], [
      s(['Sửa một lỗi trong một khoảng thời gian', 'Edit one defect within one time range'], ["Chọn mode sửa video, tải clip gốc lên, và tải thêm ảnh tham chiếu nếu được hỗ trợ. Xem clip bằng trình phát, rồi thay cả hai chỗ [mốc] bằng thời gian thật, ví dụ 00:02-00:03; đừng để lại dấu ngoặc. Ghi lại điều sẽ sửa và điều không được đổi. Tính năng chỉnh theo mốc thời gian là điều nhà phát triển công bố; việc nó khoanh đúng khoảng thời gian đến đâu còn tùy nhà cung cấp, nên bạn cần tự thử. Kiểm tra phần đầu clip, khoảng được sửa, phần cuối clip, tổng thời lượng và âm thanh. Nếu sửa ba lô mà khuôn mặt bị đổi, thì take sửa đó chưa đạt.", "Choose video edit, upload the source clip, and add a reference image if supported. Play the clip back, then replace both [time] placeholders with real times, such as 00:02-00:03; do not leave the brackets in. Write down what you will change and what must not change. Editing by time range is a capability the developer advertises; how precisely it picks out the interval depends on the provider, so you need to test it. Check the start of the clip, the edited interval, the end of the clip, the total duration and the sound. If fixing the backpack changes the face, the edit has failed."], '04-clips/edit-before-after.txt', p.timedEdit, 'video', undefined, 'Seedance 2.5'),
      s(['Thử đổi góc nhìn sau khi phần sửa đơn giản đã ổn', 'Try changing the viewpoint once a simple edit works'], ['Dùng một bản sao của clip đã duyệt và chỉ yêu cầu hạ góc nhìn xuống thấp một chút. Góc nhìn mới phải tạo ra những vùng trước đó chưa thấy, nên có nguy cơ hình khối hoặc khuôn mặt bị sai. So sánh ở cùng các mốc thời gian và giữ lại bản gốc. Nếu công cụ không có mode phù hợp, đánh dấu là chưa có; cắt khung hình trong CapCut không phải là đổi góc nhìn 3D.', 'Use a copy of an approved clip and ask only for a slightly lower viewpoint. A new viewpoint has to invent areas that were never visible, so the shapes or the face may come out wrong. Compare at the same timestamps and keep the original. If your tool has no suitable mode, mark it as unavailable; cropping the frame in CapCut is not a 3D change of viewpoint.'], '04-clips/perspective-review.txt', p.perspective, 'video', undefined, 'Seedance 2.5'),
    ], ['Có bản trước và sau ở cùng các mốc thời gian; chỉ phần cần sửa thay đổi, còn những phần phải giữ nguyên vẫn chấp nhận được.', 'You have before and after versions at the same timestamps; only the target changes, and the parts that had to stay the same are still acceptable.'], ['Nếu thay đổi lan sang chỗ khác: thu hẹp về một lỗi, hoặc làm lại cả shot; đừng ghi đè lên clip gốc.', 'If the change spreads to other parts: narrow it down to one defect, or rebuild the shot; do not overwrite the source clip.']),
    optional('sd25-audio-performance', ['Diễn xuất và kiểm tra tiếng Việt', 'Performance and checking Vietnamese speech'], ['Phân biệt lời thoại, biểu cảm, hiệu ứng âm thanh và nhạc.', 'Tell dialogue, expression, sound effects and music apart.'], ['Một shot ít chuyển động, một câu thoại ngắn do bạn tự viết, và quyền sử dụng mọi file âm thanh bạn dùng.', 'A shot with little movement, a short line you wrote yourself, and the right to use every audio file you supply.'], [
      s(['Lên kế hoạch âm thanh trước khi tạo', 'Plan the sound before you generate'], ['Chọn một ý định cảm xúc có thể nhìn thấy: nghe thấy điều gì đó, ngừng lại, nhìn xuống. Đừng đòi vui, buồn, sợ, cười và khóc trong cùng một nhịp. Lên kế hoạch ba lớp âm thanh: lời thoại rõ, tiếng môi trường nhẹ, và nhạc nếu bạn muốn. Nếu mode hỗ trợ tiếng nói bản địa thì bật âm thanh và dùng một câu ngắn. Nếu không, hãy tạo hình trước rồi thu hoặc ghép tiếng trong phần mềm dựng. Ghi chữ “Vietnamese” trong prompt không chứng minh phát âm đúng; hãy nhờ một người nghe hiểu tiếng Việt kiểm tra.', 'Choose one emotional intention you can actually see: hearing something, pausing, looking down. Do not ask for happiness, sadness, fear, laughter and tears in the same beat. Plan three layers of sound: clear dialogue, quiet ambient sound, and music if you want it. If the mode supports native speech, turn the audio on and use one short line. If it does not, make the visuals first, then record or add the sound in the editor. Writing “Vietnamese” in a prompt does not prove the pronunciation is right; ask someone who understands Vietnamese to listen and check.'], '05-edit/audio/audio-review.tsv', undefined, 'planning', [
        'Câu dự định: “Mình tìm thấy đường rồi.”\nNghe không xem chữ: người nghe chép lại gì?\nĐúng từng từ và dấu thanh? Có nuốt/nhân đôi âm?\nMôi khớp âm mở/đóng ở mốc nào?\nGiọng giữ ổn định? Tiếng nền có che câu?\nCó tiếng phát sinh ngoài ý định?\nKết quả: đạt / sửa / chưa thử; ai nghe, ngày, file.\nSửa ít tốn: rút câu hoặc dùng thu âm/voiceover có quyền; ghi rõ thay đổi.',
        'Intended line: “Mình tìm thấy đường rồi.”\nListen without the script: what does the listener transcribe?\nCorrect words and Vietnamese tones? Missing/repeated syllables?\nAt which timestamps do lip opening/closure and sound align?\nStable voice? Is dialogue masked by ambience?\nUnrequested sounds?\nResult: pass / repair / untested; reviewer, date, file.\nLower-cost repair: shorten the line or use an authorized recording/voiceover; document the substitution.',
      ], 'Seedance 2.5 / CapCut / ' + t('người nghe tiếng Việt', 'Vietnamese listener')),
      s(['Sửa phần nghe, rồi kiểm tra lại phần nhìn', 'Repair the sound, then check the picture again'], ['Nếu mode sửa video hỗ trợ chỉnh cả âm thanh lẫn hình, hãy ghi rõ khoảng thời gian và một yêu cầu duy nhất, ví dụ thay một câu nói trong khi giữ nguyên nhân vật, camera và nhịp; đừng tự bịa ra thẻ giọng nói. Nhà phát triển có công bố tính năng sửa cả nghe lẫn nhìn, nhưng khóa này chưa có clip nào được kiểm chứng. Nếu thay âm thanh trong CapCut, hãy hạ hoặc tắt track cũ trước để không bị chồng hai giọng. Dùng tai nghe kiểm tra câu đầu và câu cuối, chỗ âm thanh bị cắt và chỗ âm quá lớn, rồi nghe lại trên loa điện thoại.', 'If the video-edit mode supports changing both sound and picture, state the time range and one request, for example replacing a line while keeping the character, the camera and the timing; do not make up voice tags. The developer advertises audiovisual editing, but this course has no verified demonstration of it yet. If you replace the sound in CapCut, lower or mute the old track first so that two voices do not overlap. With headphones, check the first and last words, any place where the sound cuts, and any part that is too loud, then listen again on a phone speaker.'], '05-edit/audio/audio-repair-log.txt', undefined, 'planning', undefined, 'Seedance 2.5 / CapCut'),
    ], ['Người nghe chép lại đúng câu thoại mà không nhìn script; hình và tiếng, cả bản gốc lẫn bản đã sửa, đều được kiểm tra, hoặc được ghi là chưa thử.', 'A listener writes down the line correctly without seeing the script; the picture and sound, in both the original and the repaired version, have been checked, or are marked as untested.'], ['Nếu tiếng Việt chưa đạt: rút ngắn câu, nhờ người thu giọng, hoặc dùng lời dẫn; có tiếng thôi thì chưa đủ để chấm đạt.', 'If the Vietnamese does not come out right: shorten the line, ask someone to record it, or use a voiceover; having sound alone does not earn a pass.']),
    optional('sd25-advanced-control', ['Mô hình khối, phông xanh và nhiều nhân vật', 'Clay models, green screen and more than one character'], ['Hiểu cách kiểm soát nâng cao, và những giới hạn của thế giới vật lý vẫn còn đó.', 'Understand advanced control, and the physical limits that remain.'], ['Một video mô hình khối hoặc phông xanh do bạn tự làm hoặc có quyền dùng, các ảnh chuẩn, và một mode được hỗ trợ.', 'A clay-model or green-screen clip that you made or have permission to use, your reference images, and a supported mode.'], [
      s(['Dùng mô hình đơn giản để cố định đường đi', 'Use a simple model to fix the movement path'], ['Đây là bài nâng cao, chỉ làm sau khi bài một nhân vật đã đạt: quay hoặc dựng các khối đơn giản đại diện cho Lan và chiếc ghế, với một đường đi và một camera. Nếu mode cho phép, tải video đó lên làm tham chiếu cho chuyển động và camera, và dùng ảnh Lan, ảnh chòi để làm diện mạo. Prompt bên dưới tách biệt các vai trò này. So sánh bản khối và kết quả ở cùng các mốc thời gian: đường đi của chân, chỗ chân chạm sàn, tốc độ và camera. Một kết quả đẹp nhưng đi theo đường khác vẫn chưa đạt mục tiêu điều khiển.', 'This is an advanced exercise, to be done after the single-character task passes: film or render simple blocks standing in for Lan and the bench, with one path and one camera. If the mode allows it, upload that clip as the reference for movement and camera, and use the Lan and shelter images for appearance. The prompt below keeps those roles apart. Compare the block version and the result at the same timestamps: the path of the feet, where the feet touch the floor, the speed and the camera. A good-looking result that takes a different route has not met the goal of controlling the movement.'], '04-clips/clay-control-review.txt', p.clay, 'video', undefined, 'Seedance 2.5 + ' + t('video mô hình tự tạo', 'your clay-model clip')),
      s(['Kiểm tra phông xanh hoặc cảnh hai người tương tác', 'Check green-screen work or a two-person scene'], ['Chọn MỘT nhánh. Phông xanh: dùng clip có chủ thể tách rõ và ánh sáng đều; nếu mode có sẵn tính năng thay nền, chỉ yêu cầu đổi nền, giữ nguyên chuyển động, hình dáng và âm thanh. Nếu bạn dùng chroma key trong phần mềm dựng, hãy ghi đó là thao tác dựng, không phải bài thử tính năng của Seedance. Kiểm tra tóc, mép áo, bóng và vệt xanh dính vào chủ thể. Hai nhân vật: gắn mỗi file với đúng một vai, cho hai người đứng tách nhau và lúc đầu chỉ để một người hành động; kiểm tra xem có đổi mặt, tay chạm nhau hay che khuất nhau không. Đừng bắt đầu bằng cảnh đánh nhau hay cảnh phức tạp: giới hạn về vật lý và tương tác vẫn còn đó.', 'Choose ONE branch. Green screen: use a clip where the subject is clearly separated and the lighting is even; if the mode offers background replacement, ask only for a new background and keep the movement, the outline and the sound. If you use chroma key in the editor, label it as an editing technique, not a test of a Seedance feature. Check the hair, the edges of the clothes, the shadows and any green spill on the subject. Two characters: map each file to exactly one role, keep the two people apart, and at first let only one of them act; check for swapped faces, hands touching and one person blocking the other. Do not start with a fight or anything complicated: the limits of physics and interaction are still there.'], '04-clips/advanced-control-review.txt', undefined, 'planning', undefined, 'Seedance 2.5 / CapCut'),
    ], ['So sánh với mục tiêu điều khiển bạn đặt ra và ghi lại các lỗi còn lại; một bản demo đẹp không chứng minh mọi tính năng đều dùng được.', 'Compare the result with the control you were aiming for and write down the defects that remain; one good-looking demo does not show that every feature works.'], ['Hãy giảm mức che khuất và tương tác, hoặc giữ camera cố định; nếu mode không có, ghi trung thực là chưa có.', 'Reduce the blocking and interaction, or keep the camera fixed; if the mode is not available, say so honestly.']),
  ];

  delivery.steps.unshift(s(['Quyết định bạn sẽ nộp gì, và giữ lại bản gốc', 'Decide what you will hand in, and keep your originals'], ["Đường video: dựng các clip đã duyệt. Đường chuẩn bị: kéo ba ảnh vào timeline, để mỗi ảnh khoảng 3-5 giây, dùng chuyển cảnh cắt đơn giản và xuất một animatic; các bước import, cắt và xuất bên dưới cũng dùng được với ảnh tĩnh. Đặt tên file có chữ ANIMATIC và ghi rõ kỹ năng video chưa thử. Tạo thư mục 06-delivery chứa bản xuất, file README, danh sách đầu vào và nhật ký. Đừng xóa các take gốc khi bạn cắt bản dựng.", "Video path: edit the clips you approved. Preparation path: place three still images on the timeline, give each one about 3-5 seconds, use simple cuts and export an animatic; the import, trim and export steps below work with still images too. Put ANIMATIC in the filename and note that your video skills are untested. Create a 06-delivery folder containing the export, a README, the list of inputs and your logs. Do not delete the original takes when you trim the edit."], '06-delivery/README.txt', undefined, 'planning', undefined, 'CapCut'));
  delivery.steps.push(
    s(['Làm lại với một điều kiện thay đổi', 'Try it again with one thing changed'], ['Sau khi làm theo hướng dẫn, hãy giữ nguyên câu chuyện nhưng đổi đúng một điều: khung hình 9:16, ánh sáng ngày âm u, HOẶC nhân vật mặc áo khác. Chỉ chọn một. Liệt kê những file và prompt cần cập nhật, và những file giữ nguyên. Ví dụ, khung 9:16 có thể cắt mất chiếc ghế và chiếc đèn nên bạn cần một khung đầu mới; đừng kéo giãn ảnh 16:9. Làm một shot và giải thích bạn đã đánh đổi điều gì khi thay đổi. Bạn được nhờ trợ lý góp ý, nhưng chính bạn phải duyệt đầu vào và đưa ra quyết định cuối cùng.', 'After you have followed the guided version, keep the story but change exactly one thing: the 9:16 frame, overcast light, OR a different jacket. Choose just one. List the files and prompts that need updating and the ones that stay the same. For example, a 9:16 frame may crop out the bench and the lantern, so you need a new starting frame; do not stretch the 16:9 image. Make one shot and explain what the change cost you. An assistant may give feedback, but you approve the inputs and make the final decisions.'], '06-delivery/variation/decision-log.txt', undefined, 'planning', ['Tôi đổi:\nVì sao:\nFile cần sửa:\nPhần giữ nguyên:\nDự đoán trước tạo:\nKết quả thật hoặc chưa thử:\nĐiều học được:', 'I changed:\nReason:\nFiles to update:\nInvariants:\nPrediction before generation:\nObserved result or untested:\nWhat I learned:']),
    s(['Đồ án độc lập: một ý tưởng mới của bạn', 'Final project: a new idea of your own'], ["Tạo một câu chuyện mới, đừng chỉ đổi tên Lan rồi chép lại đúng ba shot cũ. Ví dụ: một người thợ tìm lại công cụ bị mất, một món đồ gợi lại một ký ức, hoặc một sản phẩm được dùng qua ba nhịp. Giữ trong giới hạn: một nhân vật, một địa điểm, một đạo cụ, 3-5 shot, phim dài khoảng 15-30 giây. Nộp brief, sơ đồ, ảnh chuẩn, prompt, file nguồn, nhật ký lỗi và cách sửa, và bộ phim. Giải thích ít nhất hai quyết định về mode, camera hoặc tham chiếu, và một quyết định dừng hoặc giữ take. Bạn có thể dùng ChatGPT/Claude, nhưng phải tự đọc, sửa và bảo vệ các lựa chọn của mình. Nếu thiếu credit, hãy nộp bản kế hoạch hoặc animatic; các kỹ năng video khi đó chưa được đánh giá.", "Create a new story; do not just rename Lan and copy the same three shots. Some examples: a craftsperson finds a lost tool, an object brings back a memory, or a product is used across three beats. Keep the project small: one character, one place, one prop, 3-5 shots, and a film of about 15-30 seconds. Hand in the brief, the layout, the reference images, the prompts, the source files, the log of defects and repairs, and the film. Explain at least two decisions about mode, camera or references, and one decision to stop or to keep a take. You may use ChatGPT/Claude, but you have to read, revise and stand behind your own choices. If you do not have enough credits, hand in a plan or an animatic; your video skills are then left unassessed."], '06-delivery/capstone/', p.capstone),
    s(['Chấm theo những gì bạn chứng minh được, không theo số lần bấm tạo', 'Judge what you can show, not how many times you pressed generate'], ["Dùng thang 0-3 dưới đây cho từng tiêu chí. Với việc chưa thực hiện, ghi N/A (chưa đánh giá); đừng cho 0 hay 3 theo cảm giác. Phần nền tảng chuẩn bị đạt khi Brief, Tham chiếu, Prompt và Dựng đều ≥2. Phần nền tảng video chỉ đạt khi Chuyển động, Liên tục, và Sửa lỗi & chi phí đều ≥2, kèm clip thật và mốc giây. Nếu chưa có clip, ghi “nền tảng video chưa đánh giá”. N/A không bao giờ được tính là đạt. Mức làm việc độc lập cần có đồ án mới và lý do của chính bạn, không chỉ là làm lại ví dụ. Đây là thang chấm của riêng khóa học, chưa được kiểm định bằng nghiên cứu với người học, và không tương đương một chứng chỉ nghề.", "Use the 0-3 scale below for each criterion. For anything you have not done, write N/A (not assessed); do not give it a 0 or a 3 on a hunch. The preparation foundations pass when Brief, References, Prompt and Edit are each ≥2. The video foundations pass only when Motion, Continuity and Repair & cost are each ≥2, with real clips and timestamps to show for it. If you have no clips, write “video foundations not assessed.” N/A never counts as a pass. Working independently requires a new final project and your own reasoning, not just reproducing the example. This is the course’s own scale, it has not been validated by research with learners, and it is not a professional credential."], '06-delivery/assessment.tsv', undefined, 'planning', [
      'MỨC CHUNG\n0: đã thử nhưng không thực hiện được hoặc không có bằng chứng kiểm tra.\n1: làm được một phần; cần nhắc trực tiếp, còn lỗi lớn.\n2: hoàn thành bài có giới hạn; tự kiểm tra và giải thích một cách sửa.\n3: áp dụng vào brief mới; giải thích đánh đổi, có bằng chứng và quyết định hợp lý.\nN/A: chưa thử/không thuộc đường học.\n\nTIÊU CHÍ → BẰNG CHỨNG QUAN SÁT\nBrief & mode → mục tiêu rõ, mode/giá/đầu vào thực có.\nTham chiếu → nhận diện/địa hình nhất quán; QA có lý do nhận/sửa.\nPrompt → file khớp vai trò; hành động/camera không mâu thuẫn; giải thích từng câu.\nChuyển động → hành động đọc được; không lỗi lớn về người/vật; clip thật.\nLiên tục → trạng thái/khung nối đúng; xem cả hai phía cut; clip thật.\nSửa lỗi & chi phí → mốc lỗi, giả thuyết, một thay đổi, kết quả và quyết định dừng.\nDựng & bàn giao → câu chuyện hiểu được, file phát được, âm lượng/khung hình đã kiểm.\nÂm thanh nâng cao (tùy chọn) → người nghe chép đúng câu, khớp miệng và tiếng nền hợp lý.\n\nMỗi dòng ghi: điểm / file + mốc / lý do / một việc sửa tiếp. Không cộng N/A để tạo tổng điểm giả.',
      'COMMON SCALE\n0: attempted but unable to perform, or no inspectable evidence.\n1: partial performance; direct prompting needed, major defects remain.\n2: completes the bounded task; checks output and explains one repair.\n3: transfers to a new brief; explains tradeoffs with evidence and sound decisions.\nN/A: untried/outside the selected learning path.\n\nCRITERION → OBSERVABLE EVIDENCE\nBrief & mode → clear goal, actual mode/price/inputs.\nReferences → consistent identity/geometry; reasoned accept/repair QA.\nPrompt → files match roles; action/camera are compatible; clauses explained.\nMotion → readable action without major person/prop defects; actual clip.\nContinuity → correct state/join frames; both sides of cuts inspected; actual clips.\nRepair & cost → defect timestamp, hypothesis, one change, result and stop decision.\nEdit & delivery → understandable story, playable export, reviewed sound/framing.\nAdvanced audio (optional) → listener transcribes the line, plausible lip sync and ambience.\n\nFor each row: score / file + timestamp / reason / next improvement. Do not count N/A toward a misleading total.',
    ], t('Tự đánh giá + người xem', 'Self-assessment + viewer')),
  );
  delivery.techniques = [...(delivery.techniques || []), optional('sd25-teach-back', ['Giải thích lại cho người khác', 'Explain it to someone else'], ['Tìm ra chỗ bạn chưa hiểu bằng cách giải thích cho người khác.', 'Find the gaps in your own understanding by explaining the method.'], ['Sổ thực hành của bài 5 và một người sẵn lòng nghe.', 'Your Module 5 workbook and someone willing to listen.'], [s(['Giải thích khung đầu khác ảnh tham chiếu thế nào', 'Explain how a starting frame differs from a reference image'], ['Nhờ một người đọc bài 5, rồi tự giải thích bằng lời của họ: khung đầu khác ảnh tham chiếu thế nào. Ghi lại cách họ diễn đạt, chỗ họ còn thấy rối, và một cách bạn sẽ giải thích lại. Đây là bài tập học của riêng bạn, không phải bằng chứng rằng giáo trình đã được thử với người mới học.', 'Ask someone to read Module 5 and explain, in their own words, how a starting frame differs from a reference image. Write down how they put it, where they got confused, and one way you would explain it again. This is a learning exercise for you; it is not proof that the curriculum has been tried with beginners.'], '06-delivery/teach-back.txt', undefined, 'planning', undefined, t('Bạn + người nghe', 'You + listener'))], ['Người nghe phân biệt được hai vai trò và lấy được ví dụ cho từng vai trò.', 'The listener can tell the two roles apart and give an example of each.'], ['Hãy dùng cùng một ảnh trong hai ví dụ về hai vai trò để giải thích ý định khác nhau; bạn chưa cần trả tiền để tạo gì thêm.', 'Use one image in two examples, one for each role, to show how the intention differs; you do not need to pay for any generation.'])];
  delivery.checks.push(t('Tôi có bảng chấm kèm file minh chứng; những mục chưa thử ghi N/A, và với bài làm độc lập tôi đã ghi lại các quyết định của mình.', 'My scale links to files that show the evidence; anything I have not tried is marked N/A, and for the independent project I recorded my own decisions.'));
  const titles: PromptPair[] = [
    ['Bài 1 · Câu chuyện và công cụ', 'Module 1 · Story and tools'],
    ['Bài 2 · Nhân vật và kiểm tra ảnh tham chiếu', 'Module 2 · Character and checking your references'],
    ['Bài 3 · Địa điểm, đạo cụ và bố trí cảnh', 'Module 3 · Location, props and layout'],
    ['Bài 4 · Viết và giải thích prompt', 'Module 4 · Write and explain prompts'],
    ['Bài 5 · Chuyển động, camera và sửa lỗi', 'Module 5 · Motion, camera and fixing problems'],
    ['Bài 6 · Liên tục và các mode nâng cao', 'Module 6 · Continuity and advanced modes'],
    ['Bài 7 · Dựng, bản biến thể và đồ án', 'Module 7 · Edit, variation and final project'],
  ];
  const outputs: PromptPair[] = [
    ['Ý tưởng ba shot và các công cụ sẽ dùng', 'A three-shot idea and the tools you will use'], ['Bộ nhân vật và phiếu kiểm tra ảnh', 'Character pack and image check sheet'], ['Sơ đồ, bối cảnh, đèn và khung đầu', 'Layout, location, prop and starting frame'], ['Prompt có chú giải, và các bản sửa kèm lý do', 'Prompts with notes, and revisions with reasons'], ['Nhật ký take, nguyên nhân lỗi và quyết định chi tiêu', 'Take log, what went wrong, and what you decided to spend'], ['Bảng trạng thái nối cảnh và một thử nghiệm với mode bạn chọn', 'Continuity table and one experiment with the mode you chose'], ['Phim hoặc animatic, bản biến thể, đồ án và bảng chấm', 'Film or animatic, variation, final project and scoring scale'],
  ];
  course.syllabus = course.syllabus.map((item, i) => ({ ...item, title: pick(titles[i]), minutes: [60, 90, 90, 75, 90, 90, 90][i], output: pick(outputs[i]) }));
  delivery.steps[0].downloads = [{ label: t('Bộ ảnh và phiếu thực hành trống song ngữ · ZIP', 'Images and bilingual blank worksheets · ZIP'), src: '/api/workshop/examples/sd25-practice-pack.zip' }];
  planning.steps[0].media = [image('floorplan', ['Sơ đồ trục và hai vị trí camera đã sửa', 'Repaired action-axis and camera schematic'])];
  planning.steps[0].resultReview = t('Bản nháp thật và lần sửa thật được trình bày ở phần ví dụ cuối bài. Các nhãn trên sơ đồ bằng tiếng Anh, và sơ đồ không vẽ theo tỷ lệ.', 'The actual draft and the actual repair are shown in the examples at the end of the module. The labels on the diagram are in English, and the diagram is not drawn to scale.');
  for (const asset of imageAssets.assets.filter(asset => asset.key !== 'start')) {
    const lesson = course.lessons.find(lesson => lesson.id === asset.module)!;
    (lesson.visualExamples ||= []).push({
      id: `sd25-${asset.key}`, title: `GPT Image · ${asset.key}`,
      instruction: t('Đây là ảnh thật, được tạo trong Codex. Hãy xem kết quả và nhận xét trước, rồi mới mở phần cách tạo lại. Các prompt nền tảng ở trên là bài luyện riêng, không phải câu lệnh đã dùng để tạo ảnh này.', 'This is a real image, generated in Codex. Look at the result and the review first, then open the details of how to reproduce it. The core prompts above are separate exercises; they are not the exact prompts used to make this image.'),
      settings: t('GPT Image trong Codex · 27/10/2026 · đã chạy bằng tiếng Anh. Bản tiếng Việt là bản dịch biên tập, chưa chạy lại. Công cụ không trả về phiên bản model cụ thể. Các ảnh gốc được giữ nguyên trong bộ tải về.', 'GPT Image in Codex · 27 October 2026 · run in English. The Vietnamese is an editorial translation, not a rerun. The tool did not report which exact model version it used. The original outputs are kept in the download pack.'),
      promptEn: asset.promptEn, promptVi: 'promptVi' in asset ? asset.promptVi : undefined,
      inputs: asset.inputs.map(key => ({ label: `sd25-${key}.png`, src: `/api/workshop/examples/sd25-${key}.png` })),
      outputs: [image(asset.key, [asset.key, asset.key], asset.width, asset.height)],
      review: locale === 'vi' ? asset.reviewVi : asset.reviewEn,
    });
  }
  const append = (step: LessonStep, vi: string, en: string) => { step.instruction += ' ' + t(vi, en); };
  append(planning.steps[0], 'Khi Lan nhìn ra thung lũng, mặt cô có thể bị che khuất. Hãy ghi rõ đó là chủ ý, hoặc chọn một góc quay nghiêng nhẹ để vẫn thấy một phần mặt; đừng đánh giá việc giữ khuôn mặt ở khung hình không thấy mặt.', 'When Lan looks out toward the valley, her face may be hidden. Write down that this is intentional, or choose a slight three-quarter turn; do not judge whether the face is right in a frame where the face cannot be seen.');
  if (compose) append(compose, 'Nếu bạn chưa ghép được một khung sạch trong ngân sách ảnh, hãy dùng sd25-start.png làm shot-01-start.png và chuyển cả dự án sang bộ ảnh mẫu bên dưới gồm ảnh chân dung, bảng góc nhìn, chòi và chiếc đèn. Đừng trộn với Lan do bạn tự tạo. Ghi “dùng bộ ảnh mẫu”; đây là cách để bạn tiếp tục học, không phải bằng chứng rằng việc ghép ảnh đã thành công.', 'If you cannot get a clean composite within your image budget, use sd25-start.png as shot-01-start.png and switch the whole project to the supplied portrait, turnaround, location and prop images below. Do not mix in a Lan that you generated yourself. Log “supplied asset family used”; this is a way to keep learning, not evidence that the compositing worked.');
  const languageRule = ['Chọn một ngôn ngữ prompt cho cả dự án và giữ nguyên qua các take và các lần sửa. Đổi ngôn ngữ là đổi một yếu tố, nên hãy ghi vào nhật ký. Trong khóa học này, chúng tôi chưa thử so sánh để biết ngôn ngữ nào cho kết quả tốt hơn.', 'Choose one prompt language for the whole project and keep it for every take and revision. Switching languages changes one variable, so write it in your log. We have not tested whether either language gives better results in this course.'] as const;
  append(motion.steps[4], ...languageRule); append(motion.steps[5], ...languageRule);
  append(delivery.steps[1], 'CapCut lưu các bản nháp (draft) ở một vị trí riêng của nó. Trong project-note.txt, hãy ghi tên dự án, cách mở lại bản nháp và vị trí các file nguồn; ghi chú này không phải một file dự án mà bạn bắt buộc phải xuất.', 'CapCut keeps its drafts in its own location. In project-note.txt, write down the project name, how to reopen the draft and where the source files are; this note is not a project file that you have to export.');
  // The original course is detailed. These additions close the remaining hand-offs a first-time learner needs.
  append(story.steps.at(-1)!, 'Trước khi sang bài 2, tạo các thư mục 00-project, 01-character, 02-location, 03-prompts, 04-clips, 05-edit và 06-delivery. Sao chép ảnh mẫu vào thư mục phù hợp, giữ nguyên file gốc và thêm -v02 cho bản sửa. Bạn sẽ nhìn thấy đúng đường dẫn lưu ở cuối mỗi bước; đó là nơi đặt file, không phải lệnh phải gõ.', 'Before Module 2, create 00-project, 01-character, 02-location, 03-prompts, 04-clips, 05-edit and 06-delivery. Copy the supplied image into the relevant folder, keep the original unchanged and add -v02 for a revision. The path at the end of each step tells you where to put the file; it is not a command to type.');
  append(references.steps.at(-1)!, 'Khi ảnh đầu vào là ảnh mẫu của khóa, tải nó từ thẻ hình trong bài và đặt tên đúng như dòng Lưu lại. Khi là ảnh bạn tự tạo, dùng chính file đã duyệt ở bước trước, không lấy ảnh nhỏ trong preview hoặc ảnh chụp màn hình có giao diện bao quanh.', 'When the input is a supplied course image, download it from the image card in the lesson and use the filename on the Save line. When it is your own image, use the approved file from the preceding step, not a small preview or a screenshot with interface chrome around it.');
  append(planning.steps.at(-1)!, 'Sau khi vẽ sơ đồ, tự đọc lại mỗi shot theo thứ tự: ảnh nào mở shot, Lan đứng ở đâu, chiếc đèn ở trạng thái nào, camera ở phía nào của trục. Nếu bạn không trả lời được một mục, đừng viết prompt video cho shot đó; cập nhật sơ đồ hoặc ảnh trước.', 'After drawing the layout, read each shot back in order: which image opens it, where Lan stands, what state the lantern is in, and which side of the axis the camera occupies. If you cannot answer one of those, do not write the video prompt for that shot; update the layout or image first.');
  append(frames.steps.at(-1)!, 'Chỉ sửa một loại lỗi trong mỗi v02, chẳng hạn chỉ sửa vị trí chiếc đèn hoặc chỉ sửa bàn tay. So v02 với v01 ở cùng cỡ hiển thị, ghi điều đã đổi, rồi chọn một ảnh chuẩn cho shot. Đừng dùng một ảnh đang “tạm ổn” làm đầu vào cho nhiều shot vì lỗi nhỏ sẽ lan qua cả phim.', 'Repair one kind of defect in each v02, for example the lantern position or a hand. Compare v02 with v01 at the same display size, log what changed, then choose one approved image for the shot. Do not use a “nearly good” image as the input for several shots because a small defect will spread through the film.');
  append(motion.steps.at(-1)!, 'Trước khi bấm tạo, điền một dòng nhật ký: ảnh đầu vào, mode, prompt file, thời lượng, tỷ lệ, độ phân giải, giá hiển thị và giới hạn take. Khi video xong, thêm tên file, thời gian lỗi và quyết định giữ/cắt/sửa. Nhật ký này giúp bạn biết chính xác điều nào đã thay đổi giữa hai take.', 'Before you generate, fill one log line: input image, mode, prompt file, duration, ratio, resolution, displayed price and take limit. When the video finishes, add its filename, defect timestamp and keep/trim/repair decision. The log lets you identify exactly what changed between two takes.');
  append(review.steps.at(-1)!, 'Ở mỗi điểm nối, tạm tắt âm thanh và lặp lại khoảng một giây trước và sau cut. Kiểm tra theo thứ tự: vị trí Lan, hướng nhìn, quai ba lô, vị trí ghế, rồi trạng thái đèn. Nếu chỉ một mục sai, sửa điểm nối hoặc khung đầu của shot sau; đừng đổi prompt, ảnh và camera cùng lúc.', 'At each join, temporarily mute the audio and loop about one second before and after the cut. Check in this order: Lan’s position, gaze direction, backpack straps, bench position, then lantern state. If only one item is wrong, repair the join or the next shot’s starting frame; do not change the prompt, image and camera at the same time.');
  append(delivery.steps.at(-1)!, 'Trước khi gọi là hoàn thành, mở 06-delivery trong Finder/File Explorer và kiểm tra có file MP4, project-note, export-notes, prompt đã dùng và danh sách ảnh/clip đầu vào. Nếu bạn nộp animatic, đặt ANIMATIC trong tên file và ghi rõ shot nào chưa có video thật.', 'Before you call it complete, open 06-delivery in Finder/File Explorer and check for the MP4, project-note, export-notes, prompt files actually used, and the list of input images/clips. If you submit an animatic, include ANIMATIC in its filename and state which shots have no real video yet.');
  return course;
}
